import { O as roles, t as db } from "../../../../../../chunks/db.js";
import "../../../../../../chunks/dist2.js";
import { i as superValidate, n as message, r as setError } from "../../../../../../chunks/client2.js";
import { t as zod } from "../../../../../../chunks/adapters.js";
import { t as createRoleSchema } from "../../../../../../chunks/schema5.js";
//#region src/routes/dashboard/admin-panel/roles/add-roles/+page.server.ts
var load = async () => {
	return { form: await superValidate(zod(createRoleSchema)) };
};
var actions = { add: async ({ request }) => {
	const form = await superValidate(request, zod(createRoleSchema));
	if (!form.valid) return message(form, {
		type: "error",
		text: "Please check the form for Errors"
	});
	const { name, description } = form.data;
	try {
		await db.insert(roles).values({
			name,
			description
		});
		return message(form, {
			type: "success",
			text: "Role added successfully."
		});
	} catch (err) {
		const e = err;
		if (e.code === "ER_DUP_ENTRY" || e.cause?.code === "ER_DUP_ENTRY") return setError(form, "name", "Role Name already exists.");
		console.error("Error adding role:", err);
		return message(form, {
			type: "error",
			text: "Could not add the role. Please try again."
		}, { status: 500 });
	}
} };
//#endregion
export { actions, load };
